import {
  Document, Packer, Paragraph, TextRun,
  AlignmentType, PageBreak, TabStopType
} from 'docx'
import { writeFileSync } from 'fs'

const FONT = 'Times New Roman'
const SIZE = 28
const SIZE_H1 = 32
const LINE = { line: 360, lineRule: 'auto' }
const INDENT = { firstLine: 720 }

const p = (text, opts = {}) => new Paragraph({
  children: [new TextRun({ text, font: FONT, size: SIZE, ...(opts.run || {}) })],
  spacing: { after: 0, ...LINE },
  indent: INDENT,
  alignment: AlignmentType.JUSTIFIED,
  ...(opts.para || {}),
})

const pb = (text, opts = {}) => new Paragraph({
  children: [new TextRun({ text, font: FONT, size: SIZE, bold: true, ...(opts.run || {}) })],
  spacing: { after: 0, ...LINE },
  indent: INDENT,
  alignment: AlignmentType.JUSTIFIED,
  ...(opts.para || {}),
})

const center = (text, sz, bold) => new Paragraph({
  children: [new TextRun({ text, font: FONT, size: sz || SIZE, bold: !!bold })],
  spacing: { after: 0, ...LINE },
  alignment: AlignmentType.CENTER,
})

const h1 = (text) => new Paragraph({
  children: [new TextRun({ text, font: FONT, size: SIZE_H1, bold: true })],
  spacing: { before: 360, after: 240, ...LINE },
  alignment: AlignmentType.CENTER,
})

const h2 = (text) => new Paragraph({
  children: [new TextRun({ text, font: FONT, size: SIZE, bold: true })],
  spacing: { before: 240, after: 120, ...LINE },
  alignment: AlignmentType.JUSTIFIED,
  indent: INDENT,
})

const e = () => new Paragraph({ children: [new TextRun({ text: '' })], spacing: { after: 0, ...LINE } })
const br = () => new Paragraph({ children: [new PageBreak()], spacing: { after: 0 } })

const toc = (num, title, pg) => new Paragraph({
  children: [
    new TextRun({ text: `${num}  ${title}`, font: FONT, size: SIZE }),
    new TextRun({ text: '\t', font: FONT, size: SIZE }),
    new TextRun({ text: String(pg), font: FONT, size: SIZE }),
  ],
  spacing: { after: 0, ...LINE },
  tabStops: [{ type: TabStopType.RIGHT, position: 9000 }],
})

